insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-subjects-needs-attention-and-act-now-sam-2026-11-23','decision','The Subjects college table counts the codes that need attention; the sidebar leads with ways to act','Sam, 2026-11-23 21:20Z: "For the college table, the most important thing to see on the list is a column to indicate the number of subjects that our confidence score indicates need attention. the sidebar should show immediate ways to take action." Built in #3732: Needs attention after College; the panel opens on Act on it.',array['commons','subjects','confidence','needs-attention'],'verified','PR #3732','Sam',now(),'SkyPetrel (S718)','2026-11-23'),
('r-subjects-try-web-search-sam-2026-11-23','decision','Subjects needs a try-web-search step, as the credential catalog has, and the procedures should find codes like Cerritos INST','Sam, 2026-11-23 21:20Z, on INST at Cerritos: "Seems we should have found this through our procedures...advise. Also, we need ''try web search'' like we do for our credential catalog when we need to find the cert issuer." Answered by #3732 (Search the web in the panel), #3733 (the code-address read) and #3734 (the search-page read).',array['commons','subjects','web-search','collection'],'verified','PRs #3732, #3733, #3734','Sam',now(),'SkyPetrel (S718)','2026-11-23'),
('r-subjects-card-quick-links-sections-folded-sam-2026-11-23','decision','The Commons Subjects card carries quick links under its headline and opens with its sections folded','Sam, 2026-11-23 ~21:37Z: "on subjects card tope section after the 83% header, add a short bulleted set of quick links to prioritized action needed--the links can shoot down to links on the lower sections ... we can default display the cards collapsed all but the tops sections." Built in #3732: up to five links; Collect, Curate and Connect start folded.',array['commons','subjects','card','quick-links'],'verified','PR #3732','Sam',now(),'SkyPetrel (S718)','2026-11-23'),
('f-memo-ess-26-75-errors-in-totals-rows-only-s718','fact','Memo ESS 26-75''s college and district rows match the dashboard; its errors sit in the totals rows','S718, 2026-11-24 00:20Z: all 118 college and 72 district rows match Scenario 4 (nc 15%, floor $150k). Appendix C totals read credit $4,032,606 (is $21,454,262), noncredit $108,888 (is $3,786,046); D''s total puts Calbright''s $150,000 under credit and D has no Calbright row (rows sum $25,090,309). Sam: "very help and reassiring that same errors were found".',array['implementation-funding','memo','ess-26-75','allocation'],'verified','Sam in session S718','Sam',now(),'SkyPetrel (S718)','2026-11-24'),
('d-estimating-keeps-estg-s718','decision','Estimating''s Common SUBJ is ESTG, never ESTI','S718, Sky''s call, Sam''s to revise: ESTI is the local Esthetics code at 4 cosmetology and barbering colleges, so it reads as another word. #3730 made kb/_csr_propose_codes.py, the reference''s note and kb/receipts/csr_assigned_codes_s717.json (a _corrected line) agree with kb/discipline_canonical_subj4.json, which held ESTG.',array['csr','subjects','common-subj','estimating'],'proposed','PR #3730',null,null,'SkyPetrel (S718)','2026-11-23'),
('d-subjects-needs-attention-rule-s718','decision','A local subject code needs attention when its common code is below Confident or it has no title','S718, Sky''s call, Sam''s to revise (#3732): a code needs attention when its common code is below Confident, or it has no title, no saved title and no High recommended title. A code the statewide list does not name at that college needs attention only when it has no common code. The Subjects wording follows the confidence rule; no person settles a code.',array['commons','subjects','confidence','needs-attention'],'proposed','PR #3732',null,null,'SkyPetrel (S718)','2026-11-23'),
('d-code-address-read-s718','decision','A code the catalog index omits is read once at its code''s address and filed only on a page that names it','S718, Sky''s call, Sam''s to revise (#3733): kb/_subject_code_address_probe.py reads a COCI code the index omits at its code''s address; a heading files (rule code_address) only when the page names the code in parentheses; misses go to code_address_tried. Amends S698''s never-at-an-address rule for those codes. Run 45275042093: Cerritos INST, Long Beach City CART; 22 tried.',array['commons','subjects','collection','catalog'],'proposed','PR #3733; run 45275042093',null,null,'SkyPetrel (S718)','2026-11-23'),
('d-search-page-read-s718','decision','A filed web search that found a page and no title gets that page read','S718, Sky''s call, Sam''s to revise (#3734): rule search_page reads each page a filed web search found and never titled, filing a heading only where the page names the code. Run 45283003411 read 11 pages; none names its code, all recorded as tried.',array['commons','subjects','collection','web-search'],'proposed','PR #3734; run 45283003411',null,null,'SkyPetrel (S718)','2026-11-23'),
('d-check-generated-covers-status-s718','decision','check_generated.sh covers every kb/status file or names why not; no stacked PRs','S718, Sky''s call, Sam''s to revise (#3737): scripts/check_generated.sh checks 20 of the 31 kb/status/*.json files and NOT_CHECKED names the other 11 with reasons; tests/check_generated_covers_status_test.py fails a status file in neither place. CLAUDE.md''s Branch policy forbids a PR on a branch holding another open PR''s commits.',array['ci','check-generated','guards','branch-policy'],'proposed','PR #3737',null,null,'SkyPetrel (S718)','2026-11-24'),
('p-stale-head-ci-wakes-come-from-failed-rounds-s718','pitfall','Stale-head CI wakes recur because pushes fail CI; a hand-listed check_generated.sh was the main cause','Sam, 2026-11-23 ~23:55Z: "seems like a recurring thing in sessions that we have to go back out on CIs then they are for an older head". S718: each failed round prompts a fix push, and its wake names the older head. Causes: check_generated.sh named 4 of 31 status files, an unregistered test, an http plan address, a stacked PR, a filer that re-sorted rows. Read the current head and say nothing.',array['ci','pitfall','check-generated','wakes'],'proposed','PR #3737; docs/engineering_practices_lessons.md',null,null,'SkyPetrel (S718)','2026-11-24'),
('p-tests-on-live-committed-rows-break-on-person-saves-s718','pitfall','A test that asserts on live committed rows breaks when the daily sync brings a person''s save','S718: the daily run of 2026-11-24 synced three person saves (the Clovis ANTHRO title, El Camino''s ESL credit filing, Cerritos AED as noncredit) and two tests that asserted on those rows failed; #3737 relaxed them, since person saves win. A test should judge only what it injects. Next: sweep the tests that assert on live rows.',array['tests','pitfall','person-settled','daily-sync'],'proposed','PR #3737',null,null,'SkyPetrel (S718)','2026-11-24'),
('f-southwestern-pe-likely-renamed-es-s718','fact','Southwestern''s PE/I and PE/D pages read Exercise Science (ES/I) and Dance (DANC): a likely rename, not filed','S718 (#3734, run 45283003411): Southwestern College''s page for PE/I reads "Exercise Science/Intercollegiate (ES/I)" and PE/D''s reads "Dance (DANC)". A likely code rename for kb/reference/subject_code_history/, filed only once a page prints the old and new codes together.',array['commons','subjects','subject-code-history','southwestern'],'proposed','PR #3734',null,null,'SkyPetrel (S718)','2026-11-24')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
